"""Exact Python port of OnShellBG.m (Berends-Giele for 1D water waves).

All arithmetic is exact: real quantities are fractions.Fraction; the amplitude
is complex, represented by GR (Gaussian rational: re + im*i, both Fraction).
Validated against the Wolfram BGAmplitude.
"""
from fractions import Fraction as Fr
from functools import lru_cache
from math import factorial
from itertools import permutations


class GR:
    """Gaussian rational a + b i, a,b Fraction."""
    __slots__ = ("re", "im")

    def __init__(self, re=0, im=0):
        self.re = re if isinstance(re, Fr) else Fr(re)
        self.im = im if isinstance(im, Fr) else Fr(im)

    def __add__(self, o):
        if isinstance(o, GR):
            return GR(self.re + o.re, self.im + o.im)
        return GR(self.re + o, self.im)

    __radd__ = __add__

    def __sub__(self, o):
        if isinstance(o, GR):
            return GR(self.re - o.re, self.im - o.im)
        return GR(self.re - o, self.im)

    def __rsub__(self, o):
        return GR(o - self.re, -self.im)

    def __neg__(self):
        return GR(-self.re, -self.im)

    def __mul__(self, o):
        if isinstance(o, GR):
            return GR(self.re * o.re - self.im * o.im,
                      self.re * o.im + self.im * o.re)
        return GR(self.re * o, self.im * o)

    __rmul__ = __mul__

    def __truediv__(self, o):
        # division by a real Fraction/int only (all divisions in BG are by reals)
        if isinstance(o, GR):
            d = o.re * o.re + o.im * o.im
            return GR((self.re * o.re + self.im * o.im) / d,
                      (self.im * o.re - self.re * o.im) / d)
        return GR(self.re / o, self.im / o)

    def __repr__(self):
        return f"GR({self.re}, {self.im})"


def mag(k):
    return abs(k)


# ---- Kernels (memoized on the tuple of momenta) ----
@lru_cache(maxsize=None)
def EKernel(n, ps):
    if n == 3:
        return Fr(-1, 2) * (mag(ps[0]) * mag(ps[1]) + ps[0] * ps[1])
    p1, p2, rest = ps[0], ps[1], ps[2:]
    qp2 = mag(p2)
    srest = sum(rest)
    result = qp2 ** (n - 3) * EKernel(3, (p1, p2, srest)) / Fr(factorial(n - 2))
    for m in range(1, n - 2):  # m = 1 .. n-3
        newps = (p1, p2 + sum(rest[:m])) + rest[m:]
        result -= qp2 ** m / Fr(factorial(m)) * EKernel(n - m, newps)
    return result


@lru_cache(maxsize=None)
def FKernel(n, ps):
    if n == 3:
        return Fr(-1) - ps[0] * ps[1] / (mag(ps[0]) * mag(ps[1]))
    p1, p2, rest = ps[0], ps[1], ps[2:]
    qp1, qp2 = mag(p1), mag(p2)
    result = 2 * EKernel(n, ps) / qp1
    for m in range(1, n - 2):  # m = 1 .. n-3
        sigM = p2 + sum(rest[:m])
        e = EKernel(m + 2, (-sigM, p2) + rest[:m])
        f = FKernel(n - m, (p1, sigM) + rest[m:])
        result -= 2 * e * f
    return result / qp2


def Vertex(n, moms, omegas):
    """(-I/2) * sum_{perm} omega[perm0]*omega[perm1]*FKernel[n, moms[perm]]."""
    moms = tuple(moms)
    total = Fr(0)
    for p in permutations(range(n)):
        total += omegas[p[0]] * omegas[p[1]] * FKernel(n, tuple(moms[i] for i in p))
    return GR(0, Fr(-1, 2)) * total  # (-I/2)*total ; total is real Fraction


def Propagator(omega, k, g):
    # -I / (omega^2/|k| - g)
    denom = omega * omega / mag(k) - g
    return GR(0, -1) / denom


# ---- set partitions of a list S into exactly k nonempty blocks ----
from itertools import combinations


def set_partitions(S, k):
    S = list(S)
    if k == 1:
        return [[tuple(S)]]
    if k > len(S):
        return []
    mn = min(S)
    others = [x for x in S if x != mn]
    result = []
    # first block = {mn} U sub, sub subset of others with size 0..len(S)-k
    for size in range(0, len(S) - k + 1):
        for sub in combinations(others, size):
            fp = (mn,) + sub
            rem = [x for x in S if x not in fp]
            if len(rem) >= k - 1:
                for sp in set_partitions(rem, k - 1):
                    result.append([fp] + sp)
    return result


def BGAmplitude(momenta, omegas, g):
    """Exact amplitude. momenta, omegas: lists of Fraction; g: Fraction. Returns GR."""
    momenta = [x if isinstance(x, Fr) else Fr(x) for x in momenta]
    omegas = [x if isinstance(x, Fr) else Fr(x) for x in omegas]
    g = g if isinstance(g, Fr) else Fr(g)
    n = len(momenta)
    kList = momenta
    wList = omegas

    cur_cache = {}

    def BGCurrent(S):
        # S: tuple of 1-based indices
        if len(S) == 1:
            return GR(1, 0)
        if S in cur_cache:
            return cur_cache[S]
        wS = sum(wList[i - 1] for i in S)
        kS = sum(kList[i - 1] for i in S)
        result = GR(0, 0)
        for m in range(2, len(S) + 1):
            for part in set_partitions(S, m):
                sMoms = [sum(kList[i - 1] for i in part[j]) for j in range(m)]
                sOmegas = [sum(wList[i - 1] for i in part[j]) for j in range(m)]
                vMoms = [-kS] + sMoms
                vOmegas = [-wS] + sOmegas
                term = Vertex(m + 1, vMoms, vOmegas)
                for j in range(m):
                    term = term * BGCurrent(part[j])
                result = result + term
        result = result * Propagator(wS, kS, g)
        cur_cache[S] = result
        return result

    rest = tuple(range(2, n + 1))
    result = GR(0, 0)
    for m in range(2, n):
        for part in set_partitions(rest, m):
            sMoms = [sum(kList[i - 1] for i in part[j]) for j in range(m)]
            sOmegas = [sum(wList[i - 1] for i in part[j]) for j in range(m)]
            vMoms = [kList[0]] + sMoms
            vOmegas = [wList[0]] + sOmegas
            term = Vertex(m + 1, vMoms, vOmegas)
            for j in range(m):
                term = term * BGCurrent(part[j])
            result = result + term
    return result


def make_kinematics(n, freeW, sigmas, g):
    freeW = [x if isinstance(x, Fr) else Fr(x) for x in freeW]
    g = g if isinstance(g, Fr) else Fr(g)
    assert len(freeW) == n - 2
    assert sigmas[0] + sigmas[n - 1] == 0
    sumFree = sum(freeW)
    sigmaFree = sigmas[1:n - 1]
    sumSigmaW2 = sum(sigmaFree[i] * freeW[i] ** 2 for i in range(len(freeW)))
    wn = -(sigmas[0] * sumFree ** 2 + sumSigmaW2) / (2 * sigmas[0] * sumFree)
    w1 = -(sumFree + wn)
    allW = [w1] + freeW + [wn]
    allK = [sigmas[i] * allW[i] ** 2 / g for i in range(n)]
    return allK, allW


if __name__ == "__main__":
    g = Fr(1)
    # two-minus sector
    def tm(n):
        return [-1, -1] + [1] * (n - 2)

    cases = [
        (5, [2, Fr(5, 2), 3]),
        (6, [2, Fr(5, 2), 3, Fr(7, 2)]),
        (7, [2, Fr(5, 2), 3, Fr(7, 2), 4]),
    ]
    expected = {5: GR(0, -2304), 6: GR(0, Fr(-295936, 11)), 7: GR(0, Fr(-4333568, 15))}
    for n, fw in cases:
        ks, ws = make_kinematics(n, fw, tm(n), g)
        amp = BGAmplitude(ks, ws, g)
        ok = (amp.re == expected[n].re and amp.im == expected[n].im)
        print(f"n={n}: A={amp}  expected={expected[n]}  MATCH={ok}")

Get["/home/zihanz/waterhedron_benchmark_blind/case_2/claude_opus_48_max/bg_defs.m"];
