"""Chamber-aware sampling and fitting in the two-minus sector.

Chamber signature of a point = signs of K_S = sum_{i in S} sigma_i w_i^2 for all
nonempty proper subsets S of legs.  Every |.| inside the BG kernels/propagators
is |K_{S'}| for some subset S', so a fixed signature => fixed chamber => the
amplitude is a single polynomial there.
"""
from fractions import Fraction as Fr
from itertools import combinations, combinations_with_replacement
import random
from bg import BGAmplitude, make_kinematics


def tm(n):
    return [-1, -1] + [1] * (n - 2)


def subsets(n):
    out = []
    legs = list(range(n))
    for r in range(1, n):
        for S in combinations(legs, r):
            out.append(S)
    return out


def signature(ws, sig, subs):
    out = []
    for S in subs:
        K = sum(sig[i] * ws[i] ** 2 for i in S)
        out.append(0 if K == 0 else (1 if K > 0 else -1))
    return tuple(out)


def P_at(n, ws):
    sig = tm(n)
    ks = [sig[i] * ws[i] ** 2 for i in range(n)]
    amp = BGAmplitude(ks, ws, Fr(1))
    assert amp.re == 0, amp
    return -amp.im


def onshell(n, free):
    ks, ws = make_kinematics(n, list(free), tm(n), Fr(1))
    return ws


# ---------- symmetric coordinates ----------
def esym(vals, j):
    if j == 0:
        return Fr(1)
    tot = Fr(0)
    for c in combinations(vals, j):
        p = Fr(1)
        for x in c:
            p *= x
        tot += p
    return tot


def sym_coords(n, ws):
    """(p1,p2,E3,...,E_{n-2}) ; minus legs ws[0],ws[1]; plus legs ws[2:]."""
    w1, w2 = ws[0], ws[1]
    plus = ws[2:]
    coords = [w1 + w2, w1 * w2]
    for j in range(3, n - 1):
        coords.append(esym(plus, j))
    return coords


def weighted_monomials(n):
    deg = 2 * n - 4
    weights = [1, 2] + list(range(3, n - 1))  # p1,p2,E3..E_{n-2}
    nv = len(weights)
    res = []

    def rec(idx, rem, cur):
        if idx == nv:
            if rem == 0:
                res.append(tuple(cur))
            return
        w = weights[idx]
        e = 0
        while e * w <= rem:
            rec(idx + 1, rem - e * w, cur + [e])
            e += 1
    rec(0, deg, [])
    return weights, res


# ---------- exact linear solve with held-out verification ----------
def solve_exact(A, b):
    M = len(A[0])
    rows = [list(A[i]) + [b[i]] for i in range(len(A))]
    used = [False] * len(rows)
    mat = []
    for c in range(M):
        pr = None
        for ri in range(len(rows)):
            if used[ri]:
                continue
            for (pc, prow) in mat:
                fac = rows[ri][pc]
                if fac != 0:
                    rows[ri] = [rows[ri][k] - fac * prow[k] for k in range(M + 1)]
            if rows[ri][c] != 0:
                pr = ri
                break
        if pr is None:
            raise RuntimeError(f"singular at column {c}")
        piv = rows[pr][c]
        rows[pr] = [x / piv for x in rows[pr]]
        used[pr] = True
        newmat = []
        for (pc, prow) in mat:
            fac = prow[c]
            if fac != 0:
                prow = [prow[k] - fac * rows[pr][k] for k in range(M + 1)]
            newmat.append((pc, prow))
        newmat.append((c, rows[pr]))
        mat = newmat
    x = [Fr(0)] * M
    for (pc, prow) in mat:
        x[pc] = prow[M]
    nverify = 0
    for i in range(len(A)):
        s = sum(A[i][k] * x[k] for k in range(M))
        if s != b[i]:
            raise RuntimeError(f"INCONSISTENT row {i}: {s} != {b[i]}")
        nverify += 1
    return x, nverify


def collect_chamber(n, ref_free, npts, pert=Fr(1, 50), seed=0, want_sig=None):
    """Sample on-shell points near ref_free that share a chamber signature.
    Returns (signature, list_of_ws, list_of_P)."""
    subs = subsets(n)
    rng = random.Random(seed)
    ws0 = onshell(n, ref_free)
    sig0 = signature(ws0, tm(n), subs) if want_sig is None else want_sig
    out_ws, out_P = [], []
    if want_sig is None or sig0 == signature(ws0, tm(n), subs):
        if signature(ws0, tm(n), subs) == sig0:
            out_ws.append(ws0)
            out_P.append(P_at(n, ws0))
    tries = 0
    while len(out_ws) < npts and tries < npts * 200:
        tries += 1
        free = [ref_free[i] + Fr(rng.randint(-40, 40)) * pert / 40 for i in range(n - 2)]
        if sum(free) == 0 or any(x == 0 for x in free):
            continue
        try:
            ws = onshell(n, free)
        except ZeroDivisionError:
            continue
        if signature(ws, tm(n), subs) != sig0:
            continue
        try:
            P = P_at(n, ws)
        except ZeroDivisionError:
            continue
        out_ws.append(ws)
        out_P.append(P)
    return sig0, out_ws, out_P


def fit_symmetric(n, ws_list, P_list):
    weights, monos = weighted_monomials(n)
    nv = len(weights)
    A, b = [], []
    for ws, P in zip(ws_list, P_list):
        coords = sym_coords(n, ws)
        row = []
        for e in monos:
            t = Fr(1)
            for i in range(nv):
                if e[i]:
                    t *= coords[i] ** e[i]
            row.append(t)
        A.append(row)
        b.append(P)
    x, nver = solve_exact(A, b)
    return weights, monos, x, nver

